<script setup lang="ts">import { onMounted, ref, watch } from 'vue'; import { useRoute } from 'vue-router'; import http from '../api/http'; import type { ApiResponse } from '../types'; const route=useRoute(),rows=ref<Record<string,unknown>[]>([]),loading=ref(false);async function load(){loading.value=true;try{const r=await http.get<ApiResponse<Record<string,unknown>[]>>(String(route.meta.endpoint));rows.value=r.data.data;}finally{loading.value=false;}}onMounted(load);watch(()=>route.fullPath,load);</script><template><section><h1>{{route.meta.title}}</h1><el-table :data="rows" v-loading="loading" border><el-table-column v-for="key in Object.keys(rows[0]??{})" :key="key" :prop="key" :label="key"/></el-table><el-empty v-if="!loading&&!rows.length" description="暂无数据"/></section></template>
